body:
Apache Iceberg version
1.4.1 (latest release)
Query engine
Spark
Please describe the bug 🐞
We have found that temporary views that reference an iceberg table become stale when catalog caching is enabled:  spark.sql.catalog.catalog-name.cache-enabled=true.
Initially, when a view is created
Dataset rdd = spark.read().format("iceberg").load("table1");
rdd.createOrReplaceTempView("view1");
The view and catalog cache reference the same org.apache.iceberg.Table object and the view reflects any changes that the application makes when it is queried:
spark.sql("SELECT * from view1").show();
// query returns latest state of the table
However, once cache expiry occurs (after 30 seconds by default when caching is enabled), subsequent updates to the table, such as
spark.sql("DELETE FROM table1 AS t WHERE t.id IS NULL");
cause a new entry for the table to be created in the cache and the view no longer sees any of the changes that are made---it becomes stale---because the view is still using the original org.apache.iceberg.Table object which references an Iceberg table snapshot that is now no longer current.  The view and cache are no longer in sync.
spark.sql("SELECT * from view1").show();
// No longer returns latest state of the table
The unit  test below illustrates the problem.  The test fails when the default catalog caching is enabled.
@Test
  public void testViewConsistencyAfterCacheExpiration() throws Exception {
    Assume.assumeFalse("Avro does not support metadata delete", fileFormat.equals("avro"));
    createAndInitUnpartitionedTable();

    sql("INSERT INTO TABLE %s VALUES (1, 'hr'), (2, 'hardware'), (null, 'hr')", tableName);

    Dataset<Row> rdd = spark.read().format("iceberg").load(tableName);
    rdd.createOrReplaceTempView("view1");
    assertEquals(
            "Should have expected rows",
            ImmutableList.of(row(null, "hr"),row(1, "hr"), row(2, "hardware")),
            sql("SELECT * FROM %s ORDER BY id", "view1"));

    Thread.sleep(40000);
   // Default cache expiration is 30 seconds.

    sql("DELETE FROM %s AS t WHERE t.id IS NULL", tableName);
    assertEquals(
            "Should have expected rows",
            ImmutableList.of(row(1, "hr"), row(2, "hardware")),
            sql("SELECT * FROM %s ORDER BY id", "view1"));
  }

Feature Request / Improvement
The problem is the same as has been discussed in this issue #510 and addressed in this pull request #514 :
Spark, when reading schema from avro/parquet/etc files, makes all fields optional (nullable). Additionally, arrays and maps are allowed to have null elements. check-nullability addresses the case of fields, but not arrays/maps, making writing to iceberg table fail with elements should be required, but are optional
Implementation of this change would be something like:
diff --git a/api/src/main/java/org/apache/iceberg/types/CheckCompatibility.java b/api/src/main/java/org/apache/iceberg/types/CheckCompatibility.java
index 502e52c34..02ab394ec 100644
--- a/api/src/main/java/org/apache/iceberg/types/CheckCompatibility.java
+++ b/api/src/main/java/org/apache/iceberg/types/CheckCompatibility.java
@@ -211,7 +211,7 @@ public class CheckCompatibility extends TypeUtil.CustomOrderSchemaVisitor<List<S

     this.currentType = list.elementType();
     try {
-      if (readList.isElementRequired() && list.isElementOptional()) {
+      if (checkNullability && readList.isElementRequired() && list.isElementOptional()) {
         errors.add(": elements should be required, but are optional");
       }

@@ -234,7 +234,7 @@ public class CheckCompatibility extends TypeUtil.CustomOrderSchemaVisitor<List<S
     List<String> errors = Lists.newArrayList();

     try {
-      if (readMap.isValueRequired() && map.isValueOptional()) {
+      if (checkNullability && readMap.isValueRequired() && map.isValueOptional()) {
         errors.add(": values should be required, but are optional");
       }

diff --git a/api/src/test/java/org/apache/iceberg/types/TestReadabilityChecks.java b/api/src/test/java/org/apache/iceberg/types/TestReadabilityChecks.java
index 7f5948bd5..2a1bdf625 100644
--- a/api/src/test/java/org/apache/iceberg/types/TestReadabilityChecks.java
+++ b/api/src/test/java/org/apache/iceberg/types/TestReadabilityChecks.java
@@ -525,4 +525,36 @@ public class TestReadabilityChecks {
     List<String> errors = CheckCompatibility.typeCompatibilityErrors(read, write);
     assertThat(errors).isEmpty();
   }
+
+  @Test
+  public void testCheckNullabilityRequiredListElements() {
+    Schema write =
+            new Schema(
+                    required(0, "list_field", Types.ListType.ofOptional(1, Types.IntegerType.get())));
+    Schema read =
+            new Schema(
+                    required(0, "list_field", Types.ListType.ofRequired(1, Types.IntegerType.get())));
+
+    List<String> errors = CheckCompatibility.typeCompatibilityErrors(read, write);
+    assertThat(errors).isEmpty();
+  }
+
+  @Test
+  public void testCheckNullabilityRequiredMapElements() {
+    Schema write =
+            new Schema(
+                    required(
+                            0,
+                            "map_field",
+                            Types.MapType.ofOptional(1, 2, Types.StringType.get(), Types.IntegerType.get())));
+    Schema read =
+            new Schema(
+                    required(
+                            0,
+                            "map_field",
+                            Types.MapType.ofRequired(1, 2, Types.StringType.get(), Types.IntegerType.get())));
+
+    List<String> errors = CheckCompatibility.typeCompatibilityErrors(read, write);
+    assertThat(errors).isEmpty();
+  }
 }

Query engine
None
